import{_ as e,o as r,c as n,a2 as o}from"./chunks/framework.D1UKu3SB.js";const m=JSON.parse('{"title":"SOC 2 Compliance Mapping","description":"","frontmatter":{},"headers":[],"relativePath":"SOC2-COMPLIANCE.md","filePath":"SOC2-COMPLIANCE.md","lastUpdated":1771997620000}'),a={name:"SOC2-COMPLIANCE.md"};function i(s,t,c,d,l,h){return r(),n("div",null,[...t[0]||(t[0]=[o('<h1 id="soc-2-compliance-mapping" tabindex="-1">SOC 2 Compliance Mapping <a class="header-anchor" href="#soc-2-compliance-mapping" aria-label="Permalink to &quot;SOC 2 Compliance Mapping&quot;">​</a></h1><p>This document maps how <strong>husky-config</strong> supports SOC 2 Trust Service Criteria (TSC) relevant to development and change management. It is intended for internal compliance and auditor reference.</p><hr><h2 id="what-this-husky-covers" tabindex="-1">What This Husky Covers <a class="header-anchor" href="#what-this-husky-covers" aria-label="Permalink to &quot;What This Husky Covers&quot;">​</a></h2><h3 id="_1-confidentiality-secrets-c1-cc6-1" tabindex="-1">1. <strong>Confidentiality &amp; Secrets (C1, CC6.1)</strong> <a class="header-anchor" href="#_1-confidentiality-secrets-c1-cc6-1" aria-label="Permalink to &quot;1. **Confidentiality &amp; Secrets (C1, CC6.1)**&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Control intent</th><th>How husky-config helps</th></tr></thead><tbody><tr><td>Prevent sensitive data in source code</td><td><strong>Secret scanning (secretlint)</strong> runs on every commit (full-setup). Commits containing API keys, passwords, tokens, or other detected secrets are <strong>blocked</strong>.</td></tr><tr><td>Keep env/secrets out of version control</td><td><strong><code>.env</code> in <code>.gitignore</code></strong> is ensured by the installer; <code>.secretlintrc.json</code> and <code>.secretlintignore</code> ignore env files from scanning.</td></tr></tbody></table><p><strong>Relevant hooks:</strong> Pre-commit (full-setup) runs <code>security:secrets</code> (secretlint). Installer adds/ensures <code>.env</code> in the project’s <code>.gitignore</code>.</p><hr><h3 id="_2-change-management-traceability-cc8-1" tabindex="-1">2. <strong>Change Management &amp; Traceability (CC8.1)</strong> <a class="header-anchor" href="#_2-change-management-traceability-cc8-1" aria-label="Permalink to &quot;2. **Change Management &amp; Traceability (CC8.1)**&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Control intent</th><th>How husky-config helps</th></tr></thead><tbody><tr><td>Consistent, traceable change history</td><td><strong>Commit message hook</strong> enforces <a href="https://conventionalcommits.org" target="_blank" rel="noreferrer">Conventional Commits</a>: type (feat, fix, chore, etc.), format, and length (10–100 chars). Supports audit trails and automated changelogs.</td></tr><tr><td>Commit message template</td><td><strong><code>.gitmessage</code></strong> is copied so developers get guidance and a consistent structure.</td></tr></tbody></table><p><strong>Relevant hooks:</strong> <code>commit-msg</code> validates format and length; installer copies <code>.gitmessage</code>.</p><hr><h3 id="_3-security-code-quality-cc6-1-processing-integrity" tabindex="-1">3. <strong>Security &amp; Code Quality (CC6.1, Processing Integrity)</strong> <a class="header-anchor" href="#_3-security-code-quality-cc6-1-processing-integrity" aria-label="Permalink to &quot;3. **Security &amp; Code Quality (CC6.1, Processing Integrity)**&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Control intent</th><th>How husky-config helps</th></tr></thead><tbody><tr><td>Code quality and consistency</td><td><strong>Pre-commit (lint-staged)</strong> runs Prettier (format), ESLint (lint), and cspell (spelling) on staged files. Failed checks <strong>block</strong> the commit.</td></tr><tr><td>Dependency vulnerabilities</td><td><strong>npm audit</strong> runs on pre-commit (full-setup). By default it <strong>warns</strong> only (does not block). See “Gaps and optional hardening” below to fail on vulnerabilities.</td></tr></tbody></table><p><strong>Relevant hooks:</strong> Pre-commit (full-setup) runs <code>lint-staged</code> and <code>security:secrets</code>; <code>npm run security</code> (npm audit) is run with <code>|| true</code>.</p><hr><h2 id="summary-table" tabindex="-1">Summary Table <a class="header-anchor" href="#summary-table" aria-label="Permalink to &quot;Summary Table&quot;">​</a></h2><table tabindex="0"><thead><tr><th>SOC 2–relevant area</th><th>Covered by husky-config</th><th>Notes</th></tr></thead><tbody><tr><td>Secrets in code (Confidentiality)</td><td>Yes</td><td>secretlint blocks commit; .env in .gitignore</td></tr><tr><td>Traceable commits (Change management)</td><td>Yes</td><td>Conventional commits + commit-msg hook</td></tr><tr><td>Code quality / consistency</td><td>Yes</td><td>Prettier, ESLint, cspell via lint-staged</td></tr><tr><td>Dependency vulnerabilities</td><td>Partial</td><td>npm audit runs but does not fail commit by default</td></tr><tr><td>Signed commits (identity)</td><td>No</td><td>Not enforced; use platform or policy</td></tr><tr><td>Branch protection / PR review</td><td>No</td><td>Handled by GitHub/GitLab/etc., not git hooks</td></tr></tbody></table><hr><h2 id="gaps-and-optional-hardening" tabindex="-1">Gaps and Optional Hardening <a class="header-anchor" href="#gaps-and-optional-hardening" aria-label="Permalink to &quot;Gaps and Optional Hardening&quot;">​</a></h2><p>These are <strong>not</strong> required for SOC 2 by default but are often requested or recommended:</p><ol><li><p><strong>Fail on dependency vulnerabilities</strong><br> Pre-commit runs <code>npm run security</code> but by default does not block the commit on findings. For stricter SOC 2 posture, set <strong><code>HUSKY_FAIL_ON_AUDIT=1</code></strong> (e.g. in your environment or in a <code>.env</code> used by the team) so that dependency vulnerabilities <strong>fail</strong> the commit. No hook edit required.</p></li><li><p><strong>Signed commits</strong><br> SOC 2 auditors may expect proof of who made a change. Enforce signed commits (GPG or SSH) via:</p><ul><li>A <code>commit-msg</code> or <code>pre-commit</code> check that verifies signature, or</li><li>Branch protection rules that require signed commits (e.g. on GitHub).</li></ul></li><li><p><strong>Branch protection and peer review</strong><br> These are enforced in the Git host (GitHub, GitLab, etc.), not in husky: require PR reviews, status checks, and branch protection for main/master.</p></li><li><p><strong>CI alignment</strong><br> Run the same checks (lint, secret scan, audit) in CI so that bypassing local hooks does not allow non-compliant code to be merged.</p></li></ol><hr><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li><a href="https://www.aicpa.org/topic/audit-assurance/audit-and-assurance-greater-than-soc-2" target="_blank" rel="noreferrer">SOC 2 – Trust Services Criteria (AICPA &amp; CIMA)</a></li><li><a href="https://www.aicpa.org/resources/download/2017-trust-services-criteria-with-revised-points-of-focus-2022" target="_blank" rel="noreferrer">2017 Trust Services Criteria – PDF with revised points of focus (2022)</a></li><li><a href="https://conventionalcommits.org" target="_blank" rel="noreferrer">Conventional Commits</a></li><li><a href="https://github.com/secretlint/secretlint" target="_blank" rel="noreferrer">secretlint</a></li><li><a href="https://docs.npmjs.com/cli/v10/commands/npm-audit" target="_blank" rel="noreferrer">npm audit</a></li><li><a href="https://docs.github.com/en/repositories/configuring-branches-and-merges-in-your-repository/managing-branches-and-merges-in-your-repository/managing-a-branch-protection-rule" target="_blank" rel="noreferrer">GitHub: Managing branch protection rules</a></li><li><a href="https://docs.github.com/en/authentication/managing-commit-signature-verification/signing-commits" target="_blank" rel="noreferrer">GitHub: Signing commits</a></li></ul>',25)])])}const u=e(a,[["render",i]]);export{m as __pageData,u as default};
